  1	const UserDAO = require("./user-dao").UserDAO;
  2	
  3	/* The AllocationsDAO must be constructed with a connected database object */
  4	const AllocationsDAO = function(db){
  5	
  6	    "use strict";
  7	
  8	    /* If this constructor is called without the "new" operator, "this" points
  9	     * to the global object. Log a warning and call it correctly. */
 10	    if (false === (this instanceof AllocationsDAO)) {
 11	        console.log("Warning: AllocationsDAO constructor called without 'new' operator");
 12	        return new AllocationsDAO(db);
 13	    }
 14	
 15	    const allocationsCol = db.collection("allocations");
 16	    const userDAO = new UserDAO(db);
 17	
 18	    this.update = (userId, stocks, funds, bonds, callback) => {
 19	        const parsedUserId = parseInt(userId);
 20	
 21	        // Create allocations document
 22	        const allocations = {
 23	            userId: userId,
 24	            stocks: stocks,
 25	            funds: funds,
 26	            bonds: bonds
 27	        };
 28	
 29	        allocationsCol.update({
 30	            userId: parsedUserId
 31	        }, allocations, {
 32	            upsert: true
 33	        }, err => {
 34	
 35	            if (!err) {
 36	
 37	                console.log("Updated allocations");
 38	
 39	                userDAO.getUserById(userId, (err, user) => {
 40	
 41	                    if (err) return callback(err, null);
 42	
 43	                    // add user details
 44	                    allocations.userId = userId;
 45	                    allocations.userName = user.userName;
 46	                    allocations.firstName = user.firstName;
 47	                    allocations.lastName = user.lastName;
 48	
 49	                    return callback(null, allocations);
 50	                });
 51	            }
 52	
 53	            return callback(err, null);
 54	        });
 55	    };
 56	
 57	    this.getByUserIdAndThreshold = (userId, threshold, callback) => {
 58	        const parsedUserId = parseInt(userId);
 59	
 60	        const searchCriteria = () => {
 61	
 62	            if (threshold) {
 63	                /*
 64	                // Fix for A1 - 2 NoSQL Injection - escape the threshold parameter properly
 65	                // Fix this NoSQL Injection which doesn't sanitze the input parameter 'threshold' and allows attackers
 66	                // to inject arbitrary javascript code into the NoSQL query:
 67	                // 1. 0';while(true){}'
 68	                // 2. 1'; return 1 == '1
 69	                // Also implement fix in allocations.html for UX.                             
 70	                const parsedThreshold = parseInt(threshold, 10);
 71	                
 72	                if (parsedThreshold >= 0 && parsedThreshold <= 99) {
 73	                    return {$where: `this.userId == ${parsedUserId} && this.stocks > ${parsedThreshold}`};
 74	                }
 75	                throw `The user supplied threshold: ${parsedThreshold} was not valid.`;
 76	                */
 77	                return {
 78	                    $where: `this.userId == ${parsedUserId} && this.stocks > '${threshold}'`
 79	                };
 80	            }
 81	            return {
 82	                userId: parsedUserId
 83	            };
 84	        };
 85	
 86	        allocationsCol.find(searchCriteria()).toArray((err, allocations) => {
 87	            if (err) return callback(err, null);
 88	            if (!allocations.length) return callback("ERROR: No allocations found for the user", null);
 89	
 90	            let doneCounter = 0;
 91	            const userAllocations = [];
 92	
 93	            allocations.forEach( alloc => {
 94	                userDAO.getUserById(alloc.userId, (err, user) => {
 95	                    if (err) return callback(err, null);
 96	
 97	                    alloc.userName = user.userName;
 98	                    alloc.firstName = user.firstName;
 99	                    alloc.lastName = user.lastName;
100	
101	                    doneCounter += 1;
102	                    userAllocations.push(alloc);
103	
104	                    if (doneCounter === allocations.length) {
105	                        callback(null, userAllocations);
106	                    }
107	                });
108	            });
109	        });
110	    };
111	
112	};
113	
114	module.exports.AllocationsDAO = AllocationsDAO;
